#!/usr/bin/env bash
# Run from apps/ios on a macOS runner with Xcode, cargo-tauri and the iOS target.
set -euo pipefail
[[ "$(uname -s)" == Darwin ]] || { printf 'Xcode/macOS required\n' >&2; exit 1; }
export CARGO_BUILD_JOBS=4
pnpm build
cargo tauri icon src-tauri/icons/app.svg --output src-tauri/icons
# Native files are generated by the matching Tauri CLI, never hand-maintained.
cargo tauri ios init --ci
project_count=$(find src-tauri/gen/apple -maxdepth 1 -name '*.xcodeproj' -type d | wc -l | tr -d ' ')
[[ "$project_count" == 1 ]] || { printf 'Expected one generated Xcode project\n' >&2; exit 1; }
project=$(find src-tauri/gen/apple -maxdepth 1 -name '*.xcodeproj' -type d)
xcodebuild -list -json -project "$project" > src-tauri/gen/apple/schemes.json
scheme=$(node --input-type=module -e '
  import { readFileSync } from "node:fs";
  const data = JSON.parse(readFileSync("src-tauri/gen/apple/schemes.json", "utf8"));
  const schemes = data.project.schemes.filter(name => name.endsWith("_iOS"));
  if (schemes.length !== 1) throw new Error("Expected one iOS scheme");
  console.log(schemes[0]);
')
# Build, not exportArchive: provisioning and Apple's distribution signing are unnecessary.
# custom-protocol embeds dist instead of using a development web server.
export TAURI_CONFIG='{"build":{"features":["custom-protocol"]}}'
xcodebuild -project "$project" -scheme "$scheme" -configuration Release \
  -sdk iphoneos -destination 'generic/platform=iOS' -jobs 4 \
  -derivedDataPath "$PWD/src-tauri/derived" \
  CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY='' \
  DEVELOPMENT_TEAM='' build
mkdir -p out/Payload
app_count=$(find src-tauri/derived/Build/Products/Release-iphoneos -maxdepth 1 -name '*.app' -type d | wc -l | tr -d ' ')
[[ "$app_count" == 1 ]] || { printf 'Expected one device app\n' >&2; exit 1; }
app=$(find src-tauri/derived/Build/Products/Release-iphoneos -maxdepth 1 -name '*.app' -type d)
cp -R "$app" out/Payload/
(cd out && /usr/bin/zip -qry Capri-unsigned.ipa Payload)
printf 'Unsigned IPA: apps/ios/out/Capri-unsigned.ipa\n'
